DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='recovery_app_login') THEN CREATE ROLE recovery_app_login LOGIN INHERIT; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='recovery_webhook_login') THEN CREATE ROLE recovery_webhook_login LOGIN INHERIT; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='recovery_worker_login') THEN CREATE ROLE recovery_worker_login LOGIN INHERIT; END IF; END $$;GRANT recovery_app TO recovery_app_login;GRANT recovery_webhook TO recovery_webhook_login;GRANT recovery_worker TO recovery_worker_login;